import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/api_paths.dart';import '../../core/providers.dart';import '../../state/app_state.dart';import '../../widgets/async_panel.dart';import '../../widgets/branch_selector.dart';import '../../widgets/records_list.dart';
class ReportsScreen extends ConsumerStatefulWidget{const ReportsScreen({super.key});@override ConsumerState<ReportsScreen> createState()=>_ReportsScreenState();}
class _ReportsScreenState extends ConsumerState<ReportsScreen>{String type='sales';@override Widget build(BuildContext context){final app=ref.watch(appStateProvider);final api=ref.watch(apiClientProvider);final path={'sales':ApiPaths.reportsSales,'purchase':ApiPaths.reportsPurchase,'stock':ApiPaths.reportsStock,'finance':ApiPaths.reportsFinance,'trial':ApiPaths.trialBalance}[type]!;final q=<String,dynamic>{if(app.currentBranchId!=null)'branch_id':app.currentBranchId,if(type!='stock')'from':_monthStart(),if(type!='stock')'to':_today()};if(type=='trial'){q.remove('from');q['to']=_today();}return Scaffold(appBar:AppBar(title:const Text('Reports Centre')),body:Column(children:[const Padding(padding:EdgeInsets.all(16),child:BranchSelector()),SingleChildScrollView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:16),child:SegmentedButton<String>(segments:const [ButtonSegment(value:'sales',label:Text('Sales')),ButtonSegment(value:'purchase',label:Text('Purchase')),ButtonSegment(value:'stock',label:Text('Stock')),ButtonSegment(value:'finance',label:Text('Finance')),ButtonSegment(value:'trial',label:Text('Trial Balance'))],selected:{type},onSelectionChanged:(s)=>setState(()=>type=s.first))),const SizedBox(height:8),Expanded(child:app.currentBranchId==null&&type!='trial'?const Center(child:Text('Branch select karein.')):AsyncPanel(key:ValueKey('$type-${app.currentBranchId}'),future:api.get(path,query:q),builder:(context,data)=>RecordsList(rows:(data as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList()))) ]));}
 static String _today(){final d=DateTime.now();return'${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';}static String _monthStart(){final d=DateTime.now();return'${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-01';}
}
